import random


def slow(a, s):
    count = 0
    for i in range(len(a)):
        for j in range(i + 1, len(a)):
            if a[i] + a[j] == s:
                count += 1
    return count


def fast(a, s):
    seen = {}
    count = 0
    for x in a:
        count += seen.get(s - x, 0)
        seen[x] = seen.get(x, 0) + 1
    return count


